import Foundation
import PixlBackup
import Testing
@testable import PixlLibrary

/// The stage 2b, milestone 1 golden vectors (`atlas.jsonl`, `tags.jsonl`, `dna.jsonl`, `tagfeatures.jsonl`): the genre
/// atlas lookups, the tag vector, the track DNA functions and features 4 and 24. Generated by the Android repo's
/// `./gradlew :brain:generateGolden`, copied here unchanged, together with the atlas asset itself
/// (`genre-atlas-v1.json.gz`, byte for byte: its SHA-256 is pinned below). The README beside the files says how each
/// `fn` is replayed.
@Suite("Brain stage 2b golden vectors (brainMatchesAndroid)")
struct BrainStage2bGoldenTests {
    typealias G = BrainGoldenTests
    typealias Value = BrainJson.Value

    static let atlasSha256 = "60d0291897b91ce97ec89ac2ff9d8811c79666ebdd66cdcad389e1ef33970eb4"

    /// The shipped asset, gunzipped and parsed once for the whole run.
    static let loaded: Result<GenreAtlas, Error> = Result {
        let gz = [UInt8](try G.fixtureData("genre-atlas-v1.json.gz"))
        let text = try Gzip.decompress(gz)
        return try GenreAtlas.parse(utf8: text)
    }

    static func atlas() throws -> GenreAtlas { try loaded.get() }

    static func hex(_ bytes: [UInt8]) -> String {
        let digits = Array("0123456789abcdef")
        var out = ""
        for b in bytes {
            out.append(digits[Int(b >> 4)])
            out.append(digits[Int(b & 15)])
        }
        return out
    }

    static func vector(_ v: Value?) -> Tags.Vector {
        var tags: [Tags.Tag] = []
        for item in v?.arrayValue ?? [] {
            guard let text = item.stringValue, let colon = text.firstIndex(of: ":"),
                  let id = Int(text[text.startIndex..<colon]), let q = Int(text[text.index(after: colon)...]) else { continue }
            tags.append(Tags.Tag(atlasId: id, q: q))
        }
        return Tags.Vector(tags)
    }

    static func writeVector(_ w: inout BrainJson.Writer, _ name: String, _ v: Tags.Vector) {
        w.beginArray(name)
        for t in v.tags { w.stringItem("\(t.atlasId):\(t.q)") }
        w.endArray()
    }

    static func ints(_ values: [Int]) -> [Int32] { values.map { Int32(truncatingIfNeeded: $0) } }

    static func writeInputs(_ w: inout BrainJson.Writer, _ name: String, _ inputs: [Tags.Input]) {
        w.beginArray(name)
        for i in inputs {
            w.beginObject()
            w.int("source", i.source); w.int("id", i.atlasId); w.double("conf", i.conf)
            w.endObject()
        }
        w.endArray()
    }

    // MARK: The asset

    @Test func theAtlasAssetIsTheFileAndroidShips() throws {
        let gz = [UInt8](try G.fixtureData("genre-atlas-v1.json.gz"))
        #expect(SHA256.hex(gz) == Self.atlasSha256, "the atlas asset is not the bytes Android ships (re-encoded? edited?)")
    }

    @Test func theAtlasLoadsWithItsCounts() throws {
        let atlas = try Self.atlas()
        #expect(atlas.version == 1)
        #expect(atlas.size == 2249)
        #expect(atlas.families.count == 24)
        #expect(atlas.moods.count == 40)
        #expect(atlas.allIds == atlas.allIds.sorted())
    }

    @Test func unknownGenresStayAbsent() throws {
        let atlas = try Self.atlas()
        #expect(atlas.idForName("a genre nobody ever named") == GenreAtlas.none)
        #expect(atlas.idForName("") == GenreAtlas.none)
        #expect(atlas.idForName("   ") == GenreAtlas.none)
        #expect(atlas.idForMbid("00000000-0000-0000-0000-000000000000") == GenreAtlas.none)
        // A string the source table says is not a genre never becomes one, even when its words are a genre's name.
        #expect(atlas.resolve("deezer", "All").isEmpty)
        #expect(atlas.resolve("deezer", "Kids").isEmpty)
        #expect(atlas.resolve("", "zzz unknown genre").isEmpty)
        #expect(Tags.merge(atlas, [Tags.Input(source: 3, atlasId: 30000, conf: 1.0)]).isEmpty)
    }

    @Test func aCorruptAtlasIsNoticed() throws {
        #expect(throws: AtlasError.self) { try GenreAtlas.parse(utf8: Array("[]".utf8)) }
        #expect(throws: AtlasError.self) { try GenreAtlas.parse(utf8: Array("{\"v\":2,\"g\":[]}".utf8)) }
        #expect(throws: AtlasError.self) { try GenreAtlas.parse(utf8: Array("{\"v\":1".utf8)) }
        #expect(throws: AtlasError.self) {
            try GenreAtlas.parse(utf8: Array("{\"v\":1,\"g\":[{\"i\":1,\"n\":\"a\"},{\"i\":1,\"n\":\"b\"}]}".utf8))
        }
    }

    // MARK: atlas.jsonl

    @Test func atlasMatchesAndroid() throws {
        let atlas = try Self.atlas()
        var report = G.Report(file: "atlas.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("atlas.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "meta":
                report.record(c, c.matches {
                    $0.int("version", atlas.version); $0.int("genres", atlas.size); $0.int("families", atlas.families.count)
                    $0.int("moods", atlas.moods.count)
                    $0.beginArray("familyNames"); for f in atlas.families { $0.stringItem(f) }; $0.endArray()
                    $0.beginArray("moodNames"); for m in atlas.moods { $0.stringItem(m) }; $0.endArray()
                })
            case "name":
                let id = atlas.idForName(G.string(i, "text"))
                report.record(c, c.matches { $0.int("id", id) })
            case "mbid":
                let id = atlas.idForMbid(G.string(i, "text"))
                report.record(c, c.matches { $0.int("id", id) })
            case "source":
                let source = G.string(i, "source"), raw = G.string(i, "raw")
                let ids = atlas.idsForSource(source, raw)
                let resolved = atlas.resolve(source, raw)
                report.record(c, c.matches {
                    if let ids { $0.ints("ids", Self.ints(ids)) } else { $0.nullValue("ids") }
                    $0.ints("resolved", Self.ints(resolved))
                })
            case "ancestors":
                let ids = atlas.ancestors(Int(G.int(i, "id")))
                report.record(c, c.matches { $0.ints("ids", Self.ints(ids)) })
            case "genre":
                let id = Int(G.int(i, "id"))
                guard let g = atlas.genre(id) else {
                    report.record(c, false)
                    continue
                }
                report.record(c, c.matches {
                    $0.int("family", g.family); $0.int("depth", g.depth); $0.int("eraStart", g.eraStart)
                    if let d = g.descriptor {
                        $0.beginObject("descriptor")
                        $0.int("energy", d.energy); $0.int("valence", d.valence); $0.int("danceability", d.danceability)
                        $0.int("acousticness", d.acousticness); $0.int("tempoLo", d.tempoLo); $0.int("tempoHi", d.tempoHi)
                        $0.ints("moods", Self.ints(d.moods))
                        $0.endObject()
                    } else {
                        $0.nullValue("descriptor")
                    }
                    $0.ints("parents", Self.ints(g.parents)); $0.ints("related", Self.ints(g.related))
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 700)
        #expect(counts["genre"] == 160)
        #expect(counts["ancestors"] == 120)
        #expect((counts["name"] ?? 0) >= 300)
    }

    // MARK: tags.jsonl

    @Test func tagsMatchAndroid() throws {
        let atlas = try Self.atlas()
        var report = G.Report(file: "tags.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("tags.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "merge":
                let inputs = G.array(i, "inputs").map {
                    Tags.Input(source: Int(G.int($0, "source")), atlasId: Int(G.int($0, "id")), conf: G.double($0, "conf"))
                }
                let v = Tags.merge(atlas, inputs)
                report.record(c, c.matches {
                    Self.writeVector(&$0, "tags", v)
                    $0.string("blob", Self.hex(Tags.encode(v)))
                })
            case "tagdot":
                let a = Self.vector(i["a"]), b = Self.vector(i["b"])
                report.record(c, c.matches { $0.double("dot", Tags.tagdot(a, b)) })
            case "fromArtist":
                let v = Tags.fromArtist(Self.vector(i["artist"]))
                report.record(c, c.matches { Self.writeVector(&$0, "tags", v) })
            case "inputs":
                let source = Int(G.int(i, "source"))
                let table = G.optionalString(i, "table")
                let raws = G.array(i, "raws").map {
                    Tags.Raw(G.string($0, "label"), mbid: G.string($0, "mbid"), votes: Int(G.int($0, "votes")))
                }
                let ins = Tags.inputs(atlas, source: source, table: table, raws: raws)
                let v = Tags.merge(atlas, ins)
                report.record(c, c.matches {
                    Self.writeInputs(&$0, "inputs", ins)
                    Self.writeVector(&$0, "tags", v)
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 480)
        #expect(counts["merge"] == 360)
        #expect(counts["tagdot"] == 80)
        #expect(counts["fromArtist"] == 40)
        #expect(counts["inputs"] == 6)
    }

    @Test func aBlobDecodesToTheVectorItCameFrom() throws {
        let atlas = try Self.atlas()
        var checked = 0
        for c in try G.cases("tags.jsonl") where c.fn == "merge" {
            let inputs = G.array(c.input, "inputs").map {
                Tags.Input(source: Int(G.int($0, "source")), atlasId: Int(G.int($0, "id")), conf: G.double($0, "conf"))
            }
            let v = Tags.merge(atlas, inputs)
            #expect(Tags.decode(Tags.encode(v)) == v)
            checked += 1
        }
        #expect(checked == 360)
        #expect(Tags.decode(nil).isEmpty)
        #expect(Tags.decode([1, 2]).isEmpty)
    }

    // MARK: dna.jsonl

    @Test func dnaMatchesAndroid() throws {
        let atlas = try Self.atlas()
        var report = G.Report(file: "dna.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("dna.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "mergeYear":
                let claims = G.array(i, "claims").map {
                    TrackDna.YearClaim(source: Int(G.int($0, "source")), year: Int(G.int($0, "year")))
                }
                let y = TrackDna.mergeYear(claims, maxYear: Int(G.int(i, "maxYear")))
                report.record(c, c.matches { $0.int("year", y.year); $0.int("source", y.source) })
            case "parseYear":
                let y = TrackDna.parseYear(G.string(i, "text"))
                report.record(c, c.matches { $0.int("year", y) })
            case "popDeezer":
                let p = TrackDna.popFromDeezerRank(G.long(i, "rank"))
                report.record(c, c.matches { $0.int("pop", p) })
            case "popPlays":
                let p = TrackDna.popFromPlays(G.long(i, "plays"))
                report.record(c, c.matches { $0.int("pop", p) })
            case "popListeners":
                let p = TrackDna.popFromListeners(G.long(i, "users"))
                report.record(c, c.matches { $0.int("pop", p) })
            case "mergePopularity":
                let p = TrackDna.mergePopularity(deezer: Int(G.int(i, "deezer")), youtube: Int(G.int(i, "youtube")),
                                                 listenBrainz: Int(G.int(i, "listenbrainz")))
                report.record(c, c.matches { $0.int("pop", p) })
            case "playCount":
                let n = TrackDna.parsePlayCount(G.string(i, "text"))
                report.record(c, c.matches { $0.long("plays", n) })
            case "feel":
                let tags = Self.vector(i["tags"])
                let f = TrackDna.feel(atlas, tags, gainDbX10: Int(G.int(i, "gainDbX10")))
                let moods = TrackDna.moods(atlas, tags)
                report.record(c, c.matches {
                    $0.int("energy", f.energy); $0.int("valence", f.valence); $0.ints("moods", Self.ints(moods))
                })
            case "scriptLang":
                let lang = TrackDna.scriptLang(G.string(i, "title"), artistCountry: G.string(i, "country"))
                report.record(c, c.matches { $0.int("lang", lang) })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 440)
        #expect(counts["mergeYear"] == 120)
        #expect(counts["feel"] == 140)
        #expect(counts["scriptLang"] == 133)
    }

    // MARK: tagfeatures.jsonl

    @Test func tagFeaturesMatchAndroid() throws {
        var report = G.Report(file: "tagfeatures.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("tagfeatures.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "tagAff":
                var state = Affinity.State()
                for s in G.array(i, "steps") {
                    Affinity.apply(&state, family: Family.tag, key: Int64(G.int(s, "id")), r: G.double(s, "r"),
                                   c: G.double(s, "c"), part: G.double(s, "part"), tMs: G.long(s, "tMs"))
                }
                let f = Features.tagAff(Self.vector(i["tags"]), state, nowMs: G.long(i, "nowMs"), p0: G.double(i, "p0"))
                report.record(c, c.matches { $0.double("feature", f) })
            case "sessTagPen":
                var session = SessionState()
                for s in G.array(i, "steps") {
                    Session.applyTags(&session, tags: Self.vector(s["tags"]), h: G.double(s, "h"),
                                      completed: G.bool(s, "completed"))
                }
                let read = Self.vector(i["tags"])
                let feature = Features.sessTagPen(read, session)
                let penalties = session.tagPen.sorted { $0.key < $1.key }
                report.record(c, c.matches {
                    $0.beginArray("penalties")
                    for (id, pen) in penalties {
                        $0.beginObject(); $0.int("id", id); $0.double("pen", pen); $0.endObject()
                    }
                    $0.endArray()
                    $0.double("feature", feature)
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 120)
        #expect(counts["tagAff"] == 60)
        #expect(counts["sessTagPen"] == 60)
    }

    // MARK: Features 4 and 24 in the feature vector

    @Test func aCandidateWithoutTagsLeavesFeaturesFourAndTwentyFourAtZero() throws {
        let atlas = try Self.atlas()
        let pop = atlas.idForName("pop")
        #expect(pop != GenreAtlas.none)
        let tags = Tags.merge(atlas, [Tags.Input(source: 3, atlasId: pop, conf: 1.0)])
        #expect(!tags.isEmpty)
        var affinity = Affinity.State()
        Affinity.apply(&affinity, family: Family.tag, key: Int64(pop), r: 1.0, c: 1.0, part: 1.0, tMs: 1_700_000_000_000)
        var session = SessionState()
        Session.applyTags(&session, tags: tags, h: 1.0, completed: false)
        let graph = Graph.empty
        var out = [Double](repeating: 0, count: Features.d)
        let now: Int64 = 1_700_000_100_000
        Features.compute(Candidate(rid: 1, aid: 2), arm: Arm.none, retrieval: 0.0, bestRank: 0, affinity: affinity,
                         session: session, graph: graph, nowMs: now, p0: 0.5, allNovel: false, out: &out)
        #expect(out[Features.tagAff] == 0.0 && out[Features.sessTagPen] == 0.0)
        Features.compute(Candidate(rid: 1, aid: 2, tags: tags), arm: Arm.none, retrieval: 0.0, bestRank: 0,
                         affinity: affinity, session: session, graph: graph, nowMs: now, p0: 0.5, allNovel: false, out: &out)
        #expect(out[Features.tagAff] > 0.0)
        #expect(out[Features.sessTagPen] > 0.0)
        // Nothing else moved.
        var plain = [Double](repeating: 0, count: Features.d)
        Features.compute(Candidate(rid: 1, aid: 2), arm: Arm.none, retrieval: 0.0, bestRank: 0, affinity: affinity,
                         session: session, graph: graph, nowMs: now, p0: 0.5, allNovel: false, out: &plain)
        for k in 0..<Features.d where k != Features.tagAff && k != Features.sessTagPen { #expect(out[k] == plain[k]) }
    }
}
